:"kick","data":{"kind":"channel","id":"xqc/clips","presentation":"card"}}}]}]},"expected":["PROVIDER:INVALID_ID:e1"]},{"name":"embed: kick VOD card","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"kick","data":{"kind":"video","id":"xqc/01a0df43-5130-7429-af65-66a176d79e10","presentation":"card"}}}]}]},"expected":[]},{"name":"embed: kick VOD link","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"kick","data":{"kind":"video","id":"xqc/01a0df43-5130-7429-af65-66a176d79e10","presentation":"link"}}}]}]},"expected":[]},{"name":"embed: kick VOD as a player is refused","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"kick","data":{"kind":"video","id":"xqc/01a0df43-5130-7429-af65-66a176d79e10","presentation":"embed"}}}]}]},"expected":["PROVIDER:INVALID_PRESENTATION:e1"]},{"name":"embed: kick VOD with a path trick is refused","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"kick","data":{"kind":"video","id":"../01a0df43-5130-7429-af65-66a176d79e10","presentation":"card"}}}]}]},"expected":["PROVIDER:INVALID_ID:e1"]},{"name":"embed: kick VOD with an uppercase id is refused (stored normalised)","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"kick","data":{"kind":"video","id":"xqc/01A0DF43-5130-7429-AF65-66A176D79E10","presentation":"card"}}}]}]},"expected":["PROVIDER:INVALID_ID:e1"]},{"name":"embed: facebook video card","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"facebook","data":{"kind":"video","id":"10153231379946729","presentation":"card"}}}]}]},"expected":[]},{"name":"embed: facebook reel link","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"facebook","data":{"kind":"reel","id":"1234567890123","presentation":"link"}}}]}]},"expected":[]},{"name":"embed: facebook page card","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"facebook","data":{"kind":"page","id":"NASA.page","presentation":"card"}}}]}]},"expected":[]},{"name":"embed: facebook video is never a player","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"facebook","data":{"kind":"video","id":"10153231379946729","presentation":"embed"}}}]}]},"expected":["PROVIDER:INVALID_PRESENTATION:e1"]},{"name":"embed: snapchat spotlight player","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"snapchat","data":{"kind":"spotlight","id":"W7_EDlXWTBiXAEEniNoMPwAAYdWxvYnBhaHR3AaARhNpsAaARhNmWAAAAAQ","presentation":"embed"}}}]}]},"expected":[]},{"name":"embed: snapchat profile card","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"snapchat","data":{"kind":"profile","id":"snapchat","presentation":"card"}}}]}]},"expected":[]},{"name":"embed: snapchat profile is never a player","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"snapchat","data":{"kind":"profile","id":"snapchat","presentation":"embed"}}}]}]},"expected":["PROVIDER:INVALID_PRESENTATION:e1"]},{"name":"embed: several providers in one Wall","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"a","type":"embed","x":10,"y":0,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"embed"}}},{"id":"b","type":"embed","x":10,"y":400,"width":600,"height":340,"z":0,"payload":{"providerKey":"spotify","data":{"kind":"track","id":"4uLU6hMCjMI75M1A2tKUQC","presentation":"embed"}}},{"id":"c","type":"embed","x":10,"y":800,"width":600,"height":340,"z":0,"payload":{"providerKey":"twitch","data":{"kind":"channel","id":"shroud","presentation":"card"}}},{"id":"d","type":"embed","x":10,"y":1200,"width":600,"height":340,"z":0,"payload":{"providerKey":"discord","data":{"kind":"invite","id":"abcDEF","presentation":"link"}}}]}]},"expected":[]},{"name":"embed: one bad provider among good ones reports only the bad one","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"a","type":"embed","x":10,"y":0,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"embed"}}},{"id":"b","type":"embed","x":10,"y":400,"width":600,"height":340,"z":0,"payload":{"providerKey":"spotify","data":{"kind":"track","id":"bad","presentation":"embed"}}}]}]},"expected":["PROVIDER:INVALID_ID:b"]},{"name":"mixed Wall: text, image, shapes, GamID blocks, embeds, backgrounds and stages together","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"s1","elements":[{"id":"t","type":"text","x":10,"y":0,"width":600,"height":150,"z":0,"payload":{"text":"Your text","fontFamily":"orbitron","fontSize":96,"fontWeight":700,"italic":false,"underline":false,"color":"#ffffff","align":"center","lineHeight":1.2,"letterSpacing":0,"opacity":1,"direction":"auto","wrap":true}},{"id":"i","type":"image","x":10,"y":200,"width":100,"height":100,"z":0,"payload":{"assetId":"3f2b8c1e-5a4d-4e7b-9c60-1d2e3f4a5b6c","fit":"cover","posX":50,"posY":50,"opacity":1}},{"id":"r","type":"rect","x":10,"y":400,"width":100,"height":100,"z":0,"payload":{"fill":"#aabbcc"}},{"id":"g","type":"gamid","x":10,"y":600,"width":600,"height":300,"z":0,"payload":{"block":"games","initial":10}},{"id":"e","type":"embed","x":10,"y":950,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"embed"}}}]},{"id":"s2","elements":[{"id":"f","type":"embed","x":10,"y":0,"width":600,"height":340,"z":0,"payload":{"providerKey":"steam","data":{"kind":"app","id":"730","presentation":"embed"}}}],"background":{"kind":"gradient","from":"#000000","to":"#111111","angle":90}}],"background":{"kind":"color","color":"#0d0b14"}},"expected":[]}]$w2c$::jsonb;
  default_doc jsonb := $w2d${"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[]}]}$w2d$::jsonb;
  doc_one jsonb := '{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"r1","type":"rect","x":10,"y":20,"width":300,"height":200,"z":1,"payload":{"fill":"#aabbcc"}}]}]}';
  doc_two jsonb := '{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"r1","type":"rect","x":50,"y":60,"width":300,"height":200,"z":2,"payload":{"fill":"#112233"}},{"id":"r2","type":"rect","x":0,"y":0,"width":10,"height":10,"z":0,"payload":{"fill":"#ffffff"}}]},{"id":"stage_2","elements":[]}]}';
  doc_b jsonb := '{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"only","elements":[{"id":"b1","type":"rect","x":1,"y":1,"width":5,"height":5,"z":0,"payload":{"fill":"#000000"}}]}]}';
begin
  -- real identities may already have their own private Walls; the test only ever looks at (and creates) rows for its own disposable identities
  select count(*) into rows_before from public.wall_drafts d join public.entities e on e.entity_id = d.entity_id where e.gamid_handle like 'zw2%';
  res := res || jsonb_build_object('step', 'no Wall rows exist for the disposable test identities before the test (nothing seeded)', 'pass', rows_before = 0);

  -- helper: run one statement as anon / authenticated the way PostgREST does, returning its first column or the error as ERR:sqlstate:message[:detail]
  execute $fn$
    create function pg_temp.w2_run(p_uid uuid, p_role text, p_sql text) returns text language plpgsql as $f$
    declare o text; det text;
    begin
      perform set_config('request.jwt.claims', case when p_uid is null then json_build_object('role', p_role)::text else json_build_object('sub', p_uid, 'role', p_role)::text end, true);
      execute 'set local role ' || p_role;
      begin
        execute p_sql into o;
      exception when others then
        get stacked diagnostics det = pg_exception_detail;
        o := 'ERR:' || sqlstate || ':' || sqlerrm || case when det is not null then ':' || det else '' end;
      end;
      reset role;
      return o;
    end $f$;
  $fn$;

  insert into auth.users (id, email, email_confirmed_at) values (ua, 'zw2-a@example.invalid', now()), (ub, 'zw2-b@example.invalid', now()), (uc, 'zw2-c@example.invalid', now());
  perform set_config('request.jwt.claims', json_build_object('sub', ua, 'role', 'authenticated')::text, true);
  set local role authenticated; perform 1 from public.create_solo_identity('zw2a', 'Zed A', date '1990-01-01', 'en'); reset role;
  perform set_config('request.jwt.claims', json_build_object('sub', ub, 'role', 'authenticated')::text, true);
  set local role authenticated; perform 1 from public.create_solo_identity('zw2b', 'Zed B', date '1990-01-01', 'en'); reset role;
  select e.entity_id into ent_a from public.entities e where e.gamid_handle = 'zw2a';
  select e.entity_id into ent_b from public.entities e where e.gamid_handle = 'zw2b';
  -- uc deliberately has NO identity

  -- ===== structure and privileges =====
  select relrowsecurity into flag from pg_class where oid = 'public.wall_drafts'::regclass;
  res := res || jsonb_build_object('step', 'RLS is enabled on wall_drafts', 'pass', coalesce(flag, false));
  select count(*) into cnt from pg_constraint c where c.conrelid = 'public.wall_drafts'::regclass and c.conname = 'wall_drafts_one_per_identity' and c.contype = 'u';
  res := res || jsonb_build_object('step', 'one Wall per identity is a database unique constraint', 'pass', cnt = 1);
  select count(*) into cnt from pg_constraint c where c.conrelid = 'public.wall_drafts'::regclass and c.conname = 'wall_drafts_document_is_valid' and c.contype = 'c';
  res := res || jsonb_build_object('step', 'the document validator is also a table CHECK (defense in depth)', 'pass', cnt = 1);
  select count(*) into cnt from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'wall_drafts' and c.column_name in ('owner_id', 'user_id', 'wall_count', 'is_public', 'published');
  res := res || jsonb_build_object('step', 'no owner-user, wall-count or publish columns exist (ownership is the entity; publishing is not modeled)', 'pass', cnt = 0);
  res := res || jsonb_build_object('step', 'anon has no table privilege on wall_drafts',
    'pass', not (has_table_privilege('anon', 'public.wall_drafts', 'select') or has_table_privilege('anon', 'public.wall_drafts', 'insert') or has_table_privilege('anon', 'public.wall_drafts', 'update') or has_table_privilege('anon', 'public.wall_drafts', 'delete')));
  res := res || jsonb_build_object('step', 'authenticated has no table privilege on wall_drafts (RPC-only)',
    'pass', not (has_table_privilege('authenticated', 'public.wall_drafts', 'select') or has_table_privilege('authenticated', 'public.wall_drafts', 'insert') or has_table_privilege('authenticated', 'public.wall_drafts', 'update') or has_table_privilege('authenticated', 'public.wall_drafts', 'delete')));
  res := res || jsonb_build_object('step', 'the three owner RPCs are executable by authenticated and NOT by anon',
    'pass', has_function_privilege('authenticated', 'public.ensure_my_wall_draft()', 'execute') and has_function_privilege('authenticated', 'public.get_my_wall_draft()', 'execute') and has_function_privilege('authenticated', 'public.save_my_wall_draft(jsonb,bigint)', 'execute')
      and not has_function_privilege('anon', 'public.ensure_my_wall_draft()', 'execute') and not has_function_privilege('anon', 'public.get_my_wall_draft()', 'execute') and not has_function_privilege('anon', 'public.save_my_wall_draft(jsonb,bigint)', 'execute'));
  res := res || jsonb_build_object('step', 'validators and owner resolution are not executable by any client role',
    'pass', not (has_function_privilege('authenticated', 'private.wall_document_errors(jsonb)', 'execute') or has_function_privilege('anon', 'private.wall_document_errors(jsonb)', 'execute') or has_function_privilege('authenticated', 'private.wall_owned_entity_id()', 'execute') or has_function_privilege('anon', 'private.save_my_wall_draft_impl(jsonb,bigint)', 'execute') or has_function_privilege('authenticated', 'private.wall_text_payload_errors(jsonb)', 'execute') or has_function_privilege('anon', 'private.wall_in_range(jsonb,float8,float8)', 'execute')));
  select count(*) into cnt from pg_proc p join pg_namespace s on s.oid = p.pronamespace
   where s.nspname = 'public' and p.proname in ('ensure_my_wall_draft', 'get_my_wall_draft', 'save_my_wall_draft') and p.prosecdef;
  res := res || jsonb_build_object('step', 'public wrappers are SECURITY INVOKER', 'pass', cnt = 0);
  select count(*) into cnt from pg_proc p join pg_namespace s on s.oid = p.pronamespace
   where s.nspname = 'private' and p.proname in ('ensure_my_wall_draft_impl', 'get_my_wall_draft_impl', 'save_my_wall_draft_impl', 'wall_owned_entity_id') and p.prosecdef and exists (select 1 from unnest(p.proconfig) c where c = 'search_path=""');
  res := res || jsonb_build_object('step', 'private implementations are SECURITY DEFINER with a fixed empty search_path', 'pass', cnt = 4);
  res := res || jsonb_build_object('step', 'a brand-new Wall starts as exactly the W1 createDocument() contract', 'pass', private.wall_new_document() = default_doc);

  -- ===== authentication and identity resolution =====
  out := pg_temp.w2_run(null, 'anon', 'select to_jsonb(d)::text from public.get_my_wall_draft() d');
  res := res || jsonb_build_object('step', 'anon cannot call get_my_wall_draft', 'pass', out like 'ERR:42501:%', 'got', out);
  out := pg_temp.w2_run(null, 'anon', 'select to_jsonb(d)::text from public.ensure_my_wall_draft() d');
  res := res || jsonb_build_object('step', 'anon cannot call ensure_my_wall_draft', 'pass', out like 'ERR:42501:%', 'got', out);
  out := pg_temp.w2_run(null, 'anon', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 1) d', default_doc::text));
  res := res || jsonb_build_object('step', 'anon cannot call save_my_wall_draft', 'pass', out like 'ERR:42501:%', 'got', out);
  out := pg_temp.w2_run(null, 'anon', 'select count(*)::text from public.wall_drafts');
  res := res || jsonb_build_object('step', 'anon cannot read the table directly', 'pass', out like 'ERR:42501:%', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', 'select count(*)::text from public.wall_drafts');
  res := res || jsonb_build_object('step', 'authenticated cannot read the table directly either', 'pass', out like 'ERR:42501:%', 'got', out);
  out := pg_temp.w2_run(null, 'authenticated', 'select to_jsonb(d)::text from public.ensure_my_wall_draft() d');
  res := res || jsonb_build_object('step', 'a token without a subject is AUTH_REQUIRED', 'pass', out like 'ERR:42501:AUTH_REQUIRED%', 'got', out);
  out := pg_temp.w2_run(uc, 'authenticated', 'select to_jsonb(d)::text from public.ensure_my_wall_draft() d');
  res := res || jsonb_build_object('step', 'a user with no identity gets IDENTITY_NOT_FOUND (no Wall without an identity)', 'pass', out like 'ERR:P0002:IDENTITY_NOT_FOUND%', 'got', out);

  -- ===== create / idempotency / load =====
  out := pg_temp.w2_run(ua, 'authenticated', 'select coalesce((select to_jsonb(d)::text from public.get_my_wall_draft() d), ''NONE'')');
  res := res || jsonb_build_object('step', 'get before any draft exists returns nothing', 'pass', out = 'NONE', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', 'select to_jsonb(d)::text from public.ensure_my_wall_draft() d');
  j := out::jsonb;
  res := res || jsonb_build_object('step', 'ensure creates the owner draft: revision 1, W1 default document', 'pass', (j->>'revision')::bigint = 1 and j->'document' = default_doc, 'got', out);
  res := res || jsonb_build_object('step', 'schemaVersion is preserved (1)', 'pass', (j->'document'->>'schemaVersion') = '1');
  out2 := pg_temp.w2_run(ua, 'authenticated', 'select to_jsonb(d)::text from public.ensure_my_wall_draft() d');
  res := res || jsonb_build_object('step', 'ensure is idempotent: same draft, same revision, same timestamps', 'pass', out2::jsonb = j, 'got', out2);
  out2 := pg_temp.w2_run(ua, 'authenticated', 'select (select to_jsonb(d)::text from public.get_my_wall_draft() d)');
  res := res || jsonb_build_object('step', 'the owner loads exactly what ensure returned', 'pass', out2::jsonb = j);
  select count(*) into cnt from public.wall_drafts where entity_id = ent_a;
  res := res || jsonb_build_object('step', 'exactly one Wall row exists for the identity after repeated ensure', 'pass', cnt = 1);

  -- one Wall per identity is enforced by the database itself (a client cannot bypass it; a racing second creator hits the constraint)
  begin
    insert into public.wall_drafts (entity_id, document) values (ent_a, default_doc);
    flag := false;
  exception when unique_violation then flag := true; end;
  res := res || jsonb_build_object('step', 'a second Wall for the same identity is impossible (unique_violation), even from a backend write', 'pass', flag);
  -- the race-safe path: the row already exists (as if another session just created it) and ensure must resolve to it rather than fail or duplicate
  out2 := pg_temp.w2_run(ua, 'authenticated', 'select to_jsonb(d)::text from public.ensure_my_wall_draft() d');
  select count(*) into cnt from public.wall_drafts where entity_id = ent_a;
  res := res || jsonb_build_object('step', 'ensure after a concurrent create resolves to the existing row (ON CONFLICT DO NOTHING) - never two Walls', 'pass', cnt = 1 and out2::jsonb = j);

  -- ===== save / update / revisions =====
  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 1) d', doc_one::text));
  j := out::jsonb;
  res := res || jsonb_build_object('step', 'a valid document saves and loads back unchanged', 'pass', j->'document' = doc_one and (j->>'revision')::bigint = 2, 'got', out);
  out2 := pg_temp.w2_run(ua, 'authenticated', 'select (select to_jsonb(d)::text from public.get_my_wall_draft() d)');
  res := res || jsonb_build_object('step', 'load returns the saved document and the advanced revision', 'pass', (out2::jsonb)->'document' = doc_one and ((out2::jsonb)->>'revision')::bigint = 2);
  res := res || jsonb_build_object('step', 'created_at is unchanged by a save and updated_at is not earlier', 'pass', (out2::jsonb)->>'created_at' <= (out2::jsonb)->>'updated_at');
  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 2) d', doc_two::text));
  j := out::jsonb;
  res := res || jsonb_build_object('step', 'an update persists a modified valid document and advances the revision again', 'pass', j->'document' = doc_two and (j->>'revision')::bigint = 3, 'got', out);

  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 1) d', doc_one::text));
  res := res || jsonb_build_object('step', 'a stale revision (1, current is 3) is rejected with WALL_REVISION_CONFLICT carrying the current revision', 'pass', out like 'ERR:PT409:WALL_REVISION_CONFLICT:3', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 99) d', doc_one::text));
  res := res || jsonb_build_object('step', 'a revision from the future is rejected as well', 'pass', out like 'ERR:PT409:WALL_REVISION_CONFLICT%', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', 'select (select to_jsonb(d)::text from public.get_my_wall_draft() d)');
  res := res || jsonb_build_object('step', 'the rejected stale saves changed nothing', 'pass', (out::jsonb)->'document' = doc_two and ((out::jsonb)->>'revision')::bigint = 3);
  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 0) d', doc_one::text));
  res := res || jsonb_build_object('step', 'revision 0 is INVALID_WALL_REVISION', 'pass', out like 'ERR:22023:INVALID_WALL_REVISION%', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, null::bigint) d', doc_one::text));
  res := res || jsonb_build_object('step', 'a missing revision is INVALID_WALL_REVISION', 'pass', out like 'ERR:22023:INVALID_WALL_REVISION%', 'got', out);

  -- ===== rejection (validated, never sanitized) =====
  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 3) d', '{"schemaVersion":2,"canvas":{"width":1000,"height":1778},"stages":[{"id":"s","elements":[]}]}'));
  res := res || jsonb_build_object('step', 'an unsupported schemaVersion is rejected', 'pass', out like 'ERR:22023:INVALID_WALL_DOCUMENT:%UNSUPPORTED_SCHEMA_VERSION%', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 3) d', '"just a string"'));
  res := res || jsonb_build_object('step', 'a malformed document is rejected', 'pass', out like 'ERR:22023:INVALID_WALL_DOCUMENT:%MALFORMED_DOCUMENT%', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', 'select to_jsonb(d)::text from public.save_my_wall_draft(null::jsonb, 3) d');
  res := res || jsonb_build_object('step', 'a NULL document is rejected', 'pass', out like 'ERR:22023:INVALID_WALL_DOCUMENT:%', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 3) d', '{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"s","elements":[{"id":"x","type":"video","x":0,"y":0,"width":1,"height":1,"z":0,"payload":{}}]}]}'));
  res := res || jsonb_build_object('step', 'an unknown element type is rejected', 'pass', out like 'ERR:22023:INVALID_WALL_DOCUMENT:%UNKNOWN_ELEMENT_TYPE:x%', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 3) d', '{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"s","elements":[{"id":"x","type":"rect","x":0,"y":0,"width":1,"height":1,"z":0,"payload":{"fill":"#000000","note":"<script>alert(1)</script>"}}]}]}'));
  res := res || jsonb_build_object('step', 'an unsafe <script> payload string is rejected (typed, path-addressed), not sanitized', 'pass', out like 'ERR:22023:INVALID_WALL_DOCUMENT:%UNSAFE_PAYLOAD_CONTENT:x.payload.note%', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 3) d', '{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"s","elements":[{"id":"x","type":"rect","x":0,"y":0,"width":1,"height":1,"z":0,"payload":{"fill":"#000000","a":"<iframe src=x>","b":"javascript:alert(1)","c":["onclick=go()"]}}]}]}'));
  res := res || jsonb_build_object('step', 'iframe, javascript: and event-handler payloads are all rejected', 'pass', out like '%UNSAFE_PAYLOAD_CONTENT:x.payload.a%' and out like '%UNSAFE_PAYLOAD_CONTENT:x.payload.b%' and out like '%UNSAFE_PAYLOAD_CONTENT:x.payload.c[0]%', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(jsonb_build_object(''schemaVersion'', 1, ''canvas'', jsonb_build_object(''width'', 1000, ''height'', 1778), ''stages'', jsonb_build_array(jsonb_build_object(''id'', ''s'', ''elements'', jsonb_build_array(jsonb_build_object(''id'', ''big'', ''type'', ''rect'', ''x'', 0, ''y'', 0, ''width'', 1, ''height'', 1, ''z'', 0, ''payload'', jsonb_build_object(''fill'', ''#000000'', ''pad'', repeat(''a'', 1100000))))))), %s) d', 3));
  res := res || jsonb_build_object('step', 'an oversized (>1 MiB) document is rejected', 'pass', out like 'ERR:22023:WALL_DOCUMENT_TOO_LARGE%', 'got', left(out, 200));
  out := pg_temp.w2_run(ua, 'authenticated', 'select (select to_jsonb(d)::text from public.get_my_wall_draft() d)');
  res := res || jsonb_build_object('step', 'nothing rejected was stored: document and revision are unchanged', 'pass', (out::jsonb)->'document' = doc_two and ((out::jsonb)->>'revision')::bigint = 3);

  -- the CHECK is an independent second wall: even a backend write cannot store an invalid or unsafe document
  begin update public.wall_drafts set document = '{"schemaVersion":2}' where entity_id = ent_a; flag := false; exception when check_violation then flag := true; end;
  res := res || jsonb_build_object('step', 'a direct backend write of an invalid document is blocked by the table CHECK', 'pass', flag);
  begin update public.wall_drafts set document = jsonb_set(doc_two, '{stages,0,elements,0,payload,note}', '"<script>"') where entity_id = ent_a; flag := false; exception when check_violation then flag := true; end;
  res := res || jsonb_build_object('step', 'a direct backend write of an unsafe document is blocked by the table CHECK', 'pass', flag);

  -- ===== owner isolation =====
  out := pg_temp.w2_run(ub, 'authenticated', 'select coalesce((select to_jsonb(d)::text from public.get_my_wall_draft() d), ''NONE'')');
  res := res || jsonb_build_object('step', 'another authenticated user cannot read the owner draft (sees no Wall of their own yet)', 'pass', out = 'NONE', 'got', out);
  out := pg_temp.w2_run(ub, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 3) d', doc_b::text));
  res := res || jsonb_build_object('step', 'another user cannot overwrite the owner draft: saving without a draft of their own fails and touches nothing', 'pass', out like 'ERR:P0002:WALL_DRAFT_NOT_FOUND%', 'got', out);
  out := pg_temp.w2_run(ub, 'authenticated', 'select to_jsonb(d)::text from public.ensure_my_wall_draft() d');
  res := res || jsonb_build_object('step', 'the second user gets their OWN Wall (default document, revision 1)', 'pass', ((out::jsonb)->>'revision')::bigint = 1 and (out::jsonb)->'document' = default_doc, 'got', out);
  out := pg_temp.w2_run(ub, 'authenticated', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 1) d', doc_b::text));
  res := res || jsonb_build_object('step', 'the second user saves only their own draft', 'pass', ((out::jsonb)->>'revision')::bigint = 2 and (out::jsonb)->'document' = doc_b, 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', 'select (select to_jsonb(d)::text from public.get_my_wall_draft() d)');
  res := res || jsonb_build_object('step', 'the owner draft is untouched by the other user (document and revision)', 'pass', (out::jsonb)->'document' = doc_two and ((out::jsonb)->>'revision')::bigint = 3);
  select count(*) into cnt from public.wall_drafts where entity_id in (ent_a, ent_b);
  res := res || jsonb_build_object('step', 'each identity has exactly one Wall', 'pass', cnt = 2);

  -- ===== independence from publishing =====
  out := pg_temp.w2_run(ua, 'authenticated', 'select public.set_my_identity_visibility(true)::text');
  res := res || jsonb_build_object('step', 'the identity can be published while it has a Wall draft (set_my_identity_visibility ran)', 'pass', out not like 'ERR:%', 'got', out);
  out := pg_temp.w2_run(null, 'anon', 'select public.get_public_identity(''zw2a'')::text');
  res := res || jsonb_build_object('step', 'publishing the identity does NOT publish the Wall: the public profile carries no Wall content', 'pass', out is not null and out not like 'ERR:%' and out not like '%stages%' and out not like '%schemaVersion%' and out not like '%#112233%', 'got', left(out, 300));
  out := pg_temp.w2_run(null, 'anon', 'select count(*)::text from public.wall_drafts');
  res := res || jsonb_build_object('step', 'a published identity still has no public Wall read path (anon table read denied)', 'pass', out like 'ERR:42501:%', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', 'select (select to_jsonb(d)::text from public.get_my_wall_draft() d)');
  res := res || jsonb_build_object('step', 'the owner draft is unchanged by publishing', 'pass', (out::jsonb)->'document' = doc_two and ((out::jsonb)->>'revision')::bigint = 3);
  out := pg_temp.w2_run(ua, 'authenticated', 'select public.set_my_identity_visibility(false)::text');
  out := pg_temp.w2_run(ua, 'authenticated', 'select (select to_jsonb(d)::text from public.get_my_wall_draft() d)');
  res := res || jsonb_build_object('step', 'the draft works for a private (unpublished) identity too and survives unpublishing', 'pass', (out::jsonb)->'document' = doc_two and ((out::jsonb)->>'revision')::bigint = 3);

  -- ===== Wall assets: private bucket, owner-only registry, saving only what the owner has =====
  select count(*) into cnt from storage.buckets b where b.id = 'wall-media' and b.public = false and b.file_size_limit = 5242880 and b.allowed_mime_types @> array['image/jpeg','image/png','image/webp','image/avif','image/gif'] and cardinality(b.allowed_mime_types) = 5;
  res := res || jsonb_build_object('step', 'the wall-media bucket is private, 5 MiB, and allows only jpeg/png/webp/avif/gif (no SVG)', 'pass', cnt = 1);
  select count(*) into cnt from pg_policies p where p.schemaname = 'storage' and p.tablename = 'objects' and p.policyname in ('users upload wall media to their folder', 'users read their wall media', 'users delete their wall media') and p.roles = array['authenticated']::name[];
  res := res || jsonb_build_object('step', 'wall-media has exactly the three owner-only policies, all for authenticated (no public or anon read)', 'pass', cnt = 3);
  select count(*) into cnt from pg_policies p where p.schemaname = 'storage' and p.tablename = 'objects' and (coalesce(p.qual, '') || coalesce(p.with_check, '')) like '%wall-media%' and (p.roles && array['anon', 'public']::name[]);
  res := res || jsonb_build_object('step', 'no storage policy exposes wall-media to anon/public', 'pass', cnt = 0);
  select relrowsecurity into flag from pg_class where oid = 'public.wall_assets'::regclass;
  res := res || jsonb_build_object('step', 'RLS is enabled on wall_assets and no client role has a table privilege', 'pass', coalesce(flag, false) and not (has_table_privilege('anon', 'public.wall_assets', 'select') or has_table_privilege('authenticated', 'public.wall_assets', 'select') or has_table_privilege('authenticated', 'public.wall_assets', 'insert') or has_table_privilege('authenticated', 'public.wall_assets', 'delete')));
  res := res || jsonb_build_object('step', 'asset RPCs: the owner lists / deletes (authenticated, never anon); ONLY service_role (the verifying Edge Function) registers; wrappers are SECURITY INVOKER',
    'pass', has_function_privilege('authenticated', 'public.list_my_wall_assets()', 'execute') and has_function_privilege('authenticated', 'public.delete_my_wall_asset(uuid)', 'execute')
      and not has_function_privilege('anon', 'public.list_my_wall_assets()', 'execute') and not has_function_privilege('anon', 'public.delete_my_wall_asset(uuid)', 'execute')
      and not has_function_privilege('authenticated', 'public.register_my_wall_asset(text,text,integer,integer,integer)', 'execute') and not has_function_privilege('anon', 'public.register_my_wall_asset(text,text,integer,integer,integer)', 'execute')
      and has_function_privilege('service_role', 'public.register_verified_wall_asset(uuid,text,text,integer,integer,integer,integer)', 'execute')
      and not has_function_privilege('authenticated', 'public.register_verified_wall_asset(uuid,text,text,integer,integer,integer,integer)', 'execute') and not has_function_privilege('anon', 'public.register_verified_wall_asset(uuid,text,text,integer,integer,integer,integer)', 'execute')
      and not has_function_privilege('authenticated', 'private.wall_entity_for_user(uuid)', 'execute')
      and not exists (select 1 from pg_proc p join pg_namespace s on s.oid = p.pronamespace where s.nspname = 'public' and p.proname in ('register_my_wall_asset', 'register_verified_wall_asset', 'list_my_wall_assets', 'delete_my_wall_asset') and p.prosecdef));
  out := pg_temp.w2_run(null, 'anon', 'select count(*)::text from public.list_my_wall_assets()');
  res := res || jsonb_build_object('step', 'anon cannot list assets', 'pass', out like 'ERR:42501:%', 'got', out);

  -- objects as if uploaded through the storage API (owned by the uploader, inside their own folder)
  insert into storage.objects (bucket_id, name, owner_id, metadata) values
    ('wall-media', ua::text || '/11111111-1111-4111-8111-111111111111.png', ua::text, '{"size": 2048}'),
    ('wall-media', ub::text || '/22222222-2222-4222-8222-222222222222.png', ub::text, '{"size": 4096}');
  out := pg_temp.w2_run(ua, 'authenticated', 'select count(*)::text from storage.objects where bucket_id = ''wall-media''');
  res := res || jsonb_build_object('step', 'storage RLS: a user only sees their own wall-media objects', 'pass', out = '1', 'got', out);
  out := pg_temp.w2_run(null, 'anon', 'select count(*)::text from storage.objects where bucket_id = ''wall-media''');
  res := res || jsonb_build_object('step', 'storage RLS: anon sees no wall-media objects', 'pass', out = '0' or out like 'ERR:%', 'got', out);

  -- the browser can no longer register an upload with values it claims itself: only the verifying Edge Function (service_role) can
  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(a)::text from public.register_my_wall_asset(%L, ''image/png'', 2048, 640, 360) a', ua::text || '/11111111-1111-4111-8111-111111111111.png'));
  res := res || jsonb_build_object('step', 'a signed-in browser cannot register an upload itself any more (server-side content validation only)', 'pass', out like 'ERR:42501:%', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/png'', 2048, 640, 360, null) a', ua, ua::text || '/11111111-1111-4111-8111-111111111111.png'));
  res := res || jsonb_build_object('step', 'a signed-in browser cannot call the verified registration either', 'pass', out like 'ERR:42501:%', 'got', out);
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/png'', 2048, 640, 360, null) a', ua, ua::text || '/11111111-1111-4111-8111-111111111111.png'));
  res := res || jsonb_build_object('step', 'the verifying function (service_role) registers an uploaded asset and gets its row', 'pass', out not like 'ERR:%' and (out::jsonb ->> 'width') = '640' and (out::jsonb ->> 'byte_size') = '2048', 'got', out);
  n := 0;
  j := out::jsonb;
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/png'', 2048, 640, 360, null) a', ua, ua::text || '/11111111-1111-4111-8111-111111111111.png'));
  res := res || jsonb_build_object('step', 'registering the same upload again is idempotent (same asset id)', 'pass', (out::jsonb ->> 'asset_id') = (j ->> 'asset_id'), 'got', out);
  select count(*) into cnt from public.wall_assets where entity_id = ent_a;
  res := res || jsonb_build_object('step', 'exactly one registry row exists for that upload', 'pass', cnt = 1);
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/png'', 2048, 640, 360, null) a', ua, ub::text || '/22222222-2222-4222-8222-222222222222.png'));
  res := res || jsonb_build_object('step', 'a path in ANOTHER user''s folder cannot be registered for this user', 'pass', out like 'ERR:22023:INVALID_WALL_ASSET_PATH%', 'got', out);
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/png'', 2048, 640, 360, null) a', ua, ua::text || '/33333333-3333-4333-8333-333333333333.png'));
  res := res || jsonb_build_object('step', 'registering an upload that does not exist in storage is refused', 'pass', out like 'ERR:P0002:WALL_ASSET_UPLOAD_NOT_FOUND%', 'got', out);
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/png'', 2048, 640, 360, null) a', ua, ua::text || '/../x.png'));
  res := res || jsonb_build_object('step', 'a traversal-looking path is refused', 'pass', out like 'ERR:22023:INVALID_WALL_ASSET_PATH%', 'got', out);
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/svg+xml'', 2048, 640, 360, null) a', ua, ua::text || '/11111111-1111-4111-8111-111111111111.png'));
  res := res || jsonb_build_object('step', 'SVG (or any non-raster type) is refused', 'pass', out like 'ERR:22023:INVALID_WALL_ASSET_TYPE%', 'got', out);
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/gif'', 2048, 640, 360, 5) a', ua, ua::text || '/11111111-1111-4111-8111-111111111111.png'));
  res := res || jsonb_build_object('step', 'a type that does not match the file extension is refused', 'pass', out like 'ERR:22023:INVALID_WALL_ASSET_TYPE%', 'got', out);
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/png'', 5242881, 640, 360, null) a', ua, ua::text || '/11111111-1111-4111-8111-111111111111.png'));
  res := res || jsonb_build_object('step', 'an oversized asset is refused', 'pass', out like 'ERR:22023:WALL_ASSET_TOO_LARGE%', 'got', out);
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/png'', 2048, 8193, 360, null) a', ua, ua::text || '/11111111-1111-4111-8111-111111111111.png'));
  res := res || jsonb_build_object('step', 'an asset larger than 8192 pixels on a side is refused', 'pass', out like 'ERR:22023:INVALID_WALL_ASSET_SIZE%', 'got', out);
  -- GIF: an ordinary image asset with a decode-cost limit (frames, and width x height x frames)
  insert into storage.objects (bucket_id, name, owner_id, metadata) values ('wall-media', ua::text || '/44444444-4444-4444-8444-444444444444.gif', ua::text, '{"size": 3000}');
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/gif'', 3000, 640, 360, 24) a', ua, ua::text || '/44444444-4444-4444-8444-444444444444.gif'));
  res := res || jsonb_build_object('step', 'an animated GIF within the limits registers', 'pass', out not like 'ERR:%' and (out::jsonb ->> 'mime_type') = 'image/gif', 'got', out);
  select frame_count into n from public.wall_assets where storage_path = ua::text || '/44444444-4444-4444-8444-444444444444.gif';
  res := res || jsonb_build_object('step', 'the GIF''s frame count is recorded', 'pass', n = 24);
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/gif'', 3000, 64, 64, 501) a', ua, ua::text || '/44444444-4444-4444-8444-444444444444.gif'));
  res := res || jsonb_build_object('step', 'a GIF with more than 500 frames is refused', 'pass', out like 'ERR:22023:GIF_TOO_COMPLEX%', 'got', out);
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/gif'', 3000, 4096, 4096, 3) a', ua, ua::text || '/44444444-4444-4444-8444-444444444444.gif'));
  res := res || jsonb_build_object('step', 'a GIF over 50,000,000 frame-pixels is refused (decode cost, not just file size)', 'pass', out like 'ERR:22023:GIF_TOO_COMPLEX%', 'got', out);
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/gif'', 3000, 64, 64, null) a', ua, ua::text || '/44444444-4444-4444-8444-444444444444.gif'));
  res := res || jsonb_build_object('step', 'a GIF must state its frame count', 'pass', out like 'ERR:22023:GIF_TOO_COMPLEX%', 'got', out);
  out := pg_temp.w2_run(null, 'service_role', format('select to_jsonb(a)::text from public.register_verified_wall_asset(%L::uuid, %L, ''image/png'', 2048, 640, 360, 3) a', ua, ua::text || '/11111111-1111-4111-8111-111111111111.png'));
  res := res || jsonb_build_object('step', 'only a GIF may carry a frame count', 'pass', out like 'ERR:22023:INVALID_WALL_ASSET_TYPE%', 'got', out);
  begin
    insert into public.wall_assets (entity_id, storage_path, mime_type, byte_size, width, height, frame_count) values (ent_a, ua::text || '/55555555-5555-4555-8555-555555555555.gif', 'image/gif', 100, 64, 64, 501);
    res := res || jsonb_build_object('step', 'the table itself refuses an over-limit GIF (defense in depth)', 'pass', false);
  exception when check_violation then
    res := res || jsonb_build_object('step', 'the table itself refuses an over-limit GIF (defense in depth)', 'pass', true);
  end;
  delete from public.wall_assets where storage_path = ua::text || '/44444444-4444-4444-8444-444444444444.gif';
  out := pg_temp.w2_run(ub, 'authenticated', 'select coalesce((select count(*)::text from public.list_my_wall_assets()), ''0'')');
  res := res || jsonb_build_object('step', 'another user sees none of the owner''s assets', 'pass', out = '0', 'got', out);
  out := pg_temp.w2_run(ua, 'authenticated', 'select count(*)::text from public.list_my_wall_assets()');
  res := res || jsonb_build_object('step', 'the owner lists their asset', 'pass', out = '1', 'got', out);

  -- a Wall may only use the owner's assets (image elements AND backgrounds)
